      props: { id: 'cta' },
      slots: { default: 'go' },
    })
    expect($('#cta')).toHaveLength(1)
  })

  it('renders a single child span (no fragment-level elements leak)', async () => {
    const { $ } = await render(Button, { slots: { default: 'x' } })
